from playwright.sync_api import sync_playwright
import datetime
with sync_playwright() as p:
    b=p.chromium.launch(); pg=b.new_page(viewport={'width':1440,'height':900}); errs=[]
    pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.on('console',lambda m: errs.append('C:'+m.text[:200]) if m.type=='error' and 'TUNNEL' not in m.text and 'googleapis' not in m.text and 'Failed to load resource' not in m.text else None)
    pg.goto('http://localhost:4200/login'); pg.wait_for_timeout(600); pg.click('text=Create')
    for n,v in [('ws','City Hospital'),('branch','HQ'),('dn','Admin'),('un','adm'),('pw','secret1')]: pg.fill(f'input[name={n}]',v)
    pg.click('button.go'); pg.wait_for_url('**/setup'); pg.wait_for_timeout(500)
    pg.goto('http://localhost:4200/hospital'); pg.wait_for_timeout(1200)
    print(pg.url); pg.screenshot(path='h1.png')
    pg.goto('http://localhost:4200/hospital/setup'); pg.wait_for_timeout(800)
    pg.click('text=Load sample setup'); pg.wait_for_timeout(800); pg.screenshot(path='h2.png')
    pg.goto('http://localhost:4200/hospital/patients'); pg.wait_for_timeout(800)
    pg.click('button.primary:has-text("New patient")'); pg.fill('.modal .full input >> nth=0','Mona Saleh'); pg.fill('.modal input[type=date] >> nth=0','1992-09-30')
    pg.click('.modal-foot .primary'); pg.wait_for_url('**/hospital/patients/MRN-*'); pg.wait_for_timeout(600); pg.screenshot(path='h3.png')
    print('file', pg.url)
    pg.goto('http://localhost:4200/hospital/appointments?patient=MRN-000001'); pg.wait_for_timeout(1200)
    pg.select_option('.modal select >> nth=0','DR-001'); pg.wait_for_timeout(800)
    tomorrow=(datetime.date.today()+datetime.timedelta(days=1)).isoformat()
    pg.fill('.modal input[type=date]',tomorrow); pg.wait_for_timeout(800)
    pg.click('.modal button.sm:has-text("09:00")'); pg.screenshot(path='h4.png')
    pg.click('.modal-foot .primary'); pg.wait_for_timeout(800)
    pg.fill('input[type=date] >> nth=0',tomorrow); pg.dispatch_event('input[type=date] >> nth=0','change'); pg.wait_for_timeout(800)
    print('rows', pg.locator('table.data tbody tr').count())
    first_time=pg.locator('table.data tbody tr td b').first.inner_text()
    pg.click('button.primary:has-text("Book")'); pg.wait_for_timeout(300)
    pg.fill('.modal input[placeholder*="Search"]','Ahmed'); pg.wait_for_timeout(700); pg.click('.modal .link >> nth=0')
    pg.select_option('.modal select >> nth=0','DR-001'); pg.fill('.modal input[type=date]',tomorrow)
    pg.fill('.modal input[type=time]', first_time); pg.click('.modal-foot .primary'); pg.wait_for_timeout(800)
    print('conflict:', pg.locator('.modal .flash.bad').inner_text()); pg.screenshot(path='h5.png'); pg.click('.modal-foot button >> nth=0')
    pg.click('button:has-text("Check in")'); pg.wait_for_url('**/hospital/visits/*'); pg.wait_for_timeout(1000); pg.screenshot(path='h6.png')
    pg.fill('input[type=number] >> nth=0','120'); pg.fill('input[type=number] >> nth=1','80'); pg.fill('input[type=number] >> nth=3','37')
    pg.fill('input[placeholder="ICD"]','J02'); pg.fill('input[placeholder="Diagnosis"]','Pharyngitis'); pg.click('button:has-text("Add") >> nth=0')
    pg.click('button.primary:has-text("Save")'); pg.wait_for_timeout(500)
    pg.click('button:has-text("New prescription")'); pg.wait_for_timeout(500)
    pg.select_option('.modal select >> nth=0','AMOX'); pg.fill('.modal input[placeholder="Dose"]','1 cap'); pg.fill('.modal input[placeholder="Frequency"]','3x/day'); pg.fill('.modal input[placeholder="Qty"]','15')
    pg.click('.modal-foot .primary'); pg.wait_for_timeout(700); pg.screenshot(path='h7.png')
    assert pg.locator('.warnbox').count()==1, 'no allergy warning'
    pg.fill('.warnbox input','Culture negative, tolerated before'); pg.click('.modal-foot .primary'); pg.wait_for_timeout(800)
    pg.click('button:has-text("Order lab tests")'); pg.wait_for_timeout(400); pg.check('.modal input[type=checkbox] >> nth=0'); pg.click('.modal-foot .primary'); pg.wait_for_timeout(600)
    pg.click('button:has-text("Admit") >> nth=0'); pg.wait_for_timeout(500); pg.select_option('.modal select','W1-01'); pg.click('.modal-foot .primary'); pg.wait_for_url('**/hospital/wards'); pg.wait_for_timeout(800); pg.screenshot(path='h8.png')
    pg.goto('http://localhost:4200/hospital/lab'); pg.wait_for_timeout(700); pg.click('button:has-text("Enter result")'); pg.fill('.modal input >> nth=0','450'); pg.click('.modal-foot .primary'); pg.wait_for_timeout(600)
    pg.click('.seg button:has-text("Resulted")'); pg.wait_for_timeout(500); print('lab:', pg.locator('table.data tbody tr').first.inner_text().replace('\n',' ')); pg.screenshot(path='h9.png')
    pg.goto('http://localhost:4200/hospital/pharmacy'); pg.wait_for_timeout(700)
    pg.once('dialog', lambda d: d.accept())
    pg.click('button.sm.primary'); pg.wait_for_timeout(1200)
    pg.click('.seg button:has-text("Partial")'); pg.wait_for_timeout(500); print('partial:', pg.locator('table.data tbody tr').first.inner_text().replace(chr(10),' ')); pg.screenshot(path='h10.png')
    pg.goto('http://localhost:4200/hospital/wards'); pg.wait_for_timeout(700); pg.click('.bed.Occupied button:has-text("Discharge")'); pg.fill('.modal textarea','Recovered well, follow up in 1 week'); pg.click('.modal-foot .primary'); pg.wait_for_timeout(700)
    pg.goto('http://localhost:4200/hospital/visits'); pg.wait_for_timeout(600); pg.click('table.data tbody tr'); pg.wait_for_timeout(900)
    pg.click('button.primary:has-text("Close visit")'); pg.wait_for_timeout(1200); pg.screenshot(path='h11.png')
    pg.goto('http://localhost:4200/hospital/billing'); pg.wait_for_timeout(700); pg.click('table.data tbody tr'); pg.wait_for_timeout(500); pg.screenshot(path='h12.png')
    pg.fill('.modal input[type=number]','10000'); pg.click('.modal button:has-text("Take payment")'); pg.wait_for_timeout(500); print('over:', pg.locator('.modal .flash.bad').inner_text())
    pg.fill('.modal input[type=number]','30'); pg.click('.modal button:has-text("Take payment")'); pg.wait_for_timeout(700); pg.screenshot(path='h13.png')
    pg.goto('http://localhost:4200/hospital/overview'); pg.wait_for_timeout(900); pg.screenshot(path='h14.png')
    b.close(); print('errs',errs)
